import React from 'react';
import { FaSort } from 'react-icons/fa';

function Tableau({ 
  colonnes, 
  donnees, 
  onTri, 
  actions, 
  messageVide = "Aucune donnée trouvée",
  className = ""
}) {
  return (
    <div className={`overflow-x-auto bg-white rounded-lg shadow ${className}`}>
      <table className="min-w-full divide-y divide-gray-200">
        <thead className="bg-gray-50">
          <tr>
            {colonnes.map((colonne) => (
              <th 
                key={colonne.id} 
                scope="col" 
                className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
              >
                {colonne.triable ? (
                  <button onClick={() => onTri(colonne.id)} className="flex items-center">
                    {colonne.label} <FaSort className="ml-1" />
                  </button>
                ) : (
                  colonne.label
                )}
              </th>
            ))}
            {actions && <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
              Actions
            </th>}
          </tr>
        </thead>
        <tbody className="bg-white divide-y divide-gray-200">
          {donnees.length === 0 ? (
            <tr>
              <td colSpan={colonnes.length + (actions ? 1 : 0)} className="px-6 py-4 text-center text-sm text-gray-500">
                {messageVide}
              </td>
            </tr>
          ) : (
            donnees.map((item, index) => (
              <tr key={index} className="hover:bg-gray-50">
                {colonnes.map((colonne) => (
                  <td key={colonne.id} className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {colonne.rendu ? colonne.rendu(item) : item[colonne.id]}
                  </td>
                ))}
                {actions && (
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                    {actions(item)}
                  </td>
                )}
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}

export default Tableau;
